/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_i2c.c
 *
 * D13x DesignWare I2C 控制器驱动 (NuttX i2c_ops_s 接口)
 * 参考: luban-lite hal_i2c.h + hal_i2c.c
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/compiler.h>
#include <nuttx/i2c/i2c_master.h>
#include <stdint.h>
#include <string.h>
#include <assert.h>
#include <debug.h>

#include "chip.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* DesignWare I2C 寄存器偏移 (来源: hal_i2c.h) */

#define I2C_CTL              0x00
#define I2C_TAR              0x04
#define I2C_SAR              0x08
#define I2C_DATA_CMD         0x10
#define I2C_SS_SCL_HCNT      0x20
#define I2C_SS_SCL_LCNT      0x24
#define I2C_FS_SCL_HCNT      0x28
#define I2C_FS_SCL_LCNT      0x2C
#define I2C_SDA_HOLD         0x30
#define I2C_INTR_MASK        0x38
#define I2C_INTR_CLR         0x3C
#define I2C_INTR_RAW_STAT    0x40
#define I2C_ENABLE           0x48
#define I2C_ENABLE_STATUS    0x4C
#define I2C_STATUS           0x50
#define I2C_TX_ABRT_SOURCE   0x54
#define I2C_RX_TL            0x90
#define I2C_TX_TL            0x94
#define I2C_TXFLR            0x98
#define I2C_RXFLR            0x9C

/* CTL 寄存器位定义 */

#define I2C_CTL_MASTER               (1 << 0)
#define I2C_CTL_SPEED_SS             (0x1 << 4)
#define I2C_CTL_SPEED_FS             (0x2 << 4)
#define I2C_CTL_SPEED_MASK           (3 << 4)
#define I2C_CTL_RESTART_EN           (1 << 6)

/* DATA_CMD 寄存器位定义 */

#define I2C_DATA_CMD_READ            (1 << 8)
#define I2C_DATA_CMD_STOP            (1 << 9)
#define I2C_DATA_CMD_RESTART         (1 << 10)

/* 中断位定义 */

#define I2C_INTR_RX_FULL             (1 << 2)
#define I2C_INTR_TX_EMPTY            (1 << 4)
#define I2C_INTR_TX_ABRT             (1 << 6)
#define I2C_INTR_STOP_DET            (1 << 9)
#define I2C_INTR_MASTER_TX_MASK      \
    (I2C_INTR_TX_EMPTY | I2C_INTR_TX_ABRT | I2C_INTR_STOP_DET)
#define I2C_INTR_MASTER_RX_MASK      \
    (I2C_INTR_RX_FULL | I2C_INTR_TX_ABRT | I2C_INTR_STOP_DET)

/* 使能/禁用 */

#define I2C_ENABLE_BIT               (1 << 0)

/* 状态 */

#define I2C_STATUS_BUSY              (1 << 0)

/* FIFO 深度 */

#define I2C_FIFO_DEPTH               8

/* Fast Mode 最小 SCL 时序 (来源: hal_i2c.h) */

#define FS_MIN_SCL_HIGH              600
#define FS_MIN_SCL_LOW               1300

/* 超时 (ms) */

#define I2C_TIMEOUT_MS               1000

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct d13x_i2c_dev_s
{
  struct i2c_master_s  dev;       /* NuttX I2C upper-half */
  uint32_t             base;      /* 寄存器基地址 */
  uint32_t             freq;      /* 当前 SCL 频率 */
  uint8_t              irq;       /* 中断号 */
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static int  d13x_i2c_transfer(FAR struct i2c_master_s *dev,
                               FAR struct i2c_msg_s *msgs, int count);
static int  d13x_i2c_setup(FAR struct i2c_master_s *dev);
static int  d13x_i2c_shutdown(FAR struct i2c_master_s *dev);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct i2c_ops_s g_d13x_i2c_ops =
{
  .transfer  = d13x_i2c_transfer,
  .setup     = d13x_i2c_setup,
  .shutdown  = d13x_i2c_shutdown,
};

/* 三个 I2C 实例 */

static struct d13x_i2c_dev_s g_d13x_i2c0 =
{
  .dev  = { &g_d13x_i2c_ops },
  .base = D13X_I2C0_BASE,
  .freq = 400000,
  .irq  = 84,
};

static struct d13x_i2c_dev_s g_d13x_i2c1 =
{
  .dev  = { &g_d13x_i2c_ops },
  .base = D13X_I2C1_BASE,
  .freq = 400000,
  .irq  = 85,
};

static struct d13x_i2c_dev_s g_d13x_i2c2 =
{
  .dev  = { &g_d13x_i2c_ops },
  .base = D13X_I2C2_BASE,
  .freq = 400000,
  .irq  = 86,
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static inline void i2c_putreg(uint32_t base, uint32_t offset, uint32_t val)
{
  putreg32(val, base + offset);
}

static inline uint32_t i2c_getreg(uint32_t base, uint32_t offset)
{
  return getreg32(base + offset);
}

static inline void i2c_module_enable(uint32_t base)
{
  uint32_t reg = i2c_getreg(base, I2C_ENABLE);
  reg |= I2C_ENABLE_BIT;
  i2c_putreg(base, I2C_ENABLE, reg);
}

static inline void i2c_module_disable(uint32_t base)
{
  i2c_putreg(base, I2C_INTR_CLR, 0xffff);
  uint32_t reg = i2c_getreg(base, I2C_ENABLE);
  reg &= ~I2C_ENABLE_BIT;
  i2c_putreg(base, I2C_ENABLE, reg);
}

static inline int i2c_wait_bus_idle(uint32_t base, uint32_t timeout_ms)
{
  uint32_t elapsed = 0;
  while (i2c_getreg(base, I2C_ENABLE_STATUS) & I2C_ENABLE_BIT)
    {
      if (elapsed++ >= timeout_ms * 1000)
        {
          return -ETIMEDOUT;
        }
      up_udelay(1);
    }
  return OK;
}

/****************************************************************************
 * Name: d13x_i2c_set_speed
 *
 * Description:
 *   设置 I2C SCL 时序 (Fast Mode 400KHz)
 *
 ****************************************************************************/

static void d13x_i2c_set_speed(uint32_t base, uint32_t pclk)
{
  uint32_t reg;
  uint32_t hcnt;
  uint32_t lcnt;

  /* Fast Mode: HCNT = pclk/freq - 1, LCNT = pclk/freq */

  hcnt = pclk / 400000 - 1;
  lcnt = pclk / 400000;

  /* Clamp 到最小值 (来源: hal_i2c.h + 历史经验) */

  if (hcnt < FS_MIN_SCL_HIGH)
    {
      hcnt = FS_MIN_SCL_HIGH;
    }

  if (lcnt < FS_MIN_SCL_LOW)
    {
      lcnt = FS_MIN_SCL_LOW;
    }

  /* 设置 Fast Mode 速度 */

  reg = i2c_getreg(base, I2C_CTL);
  reg &= ~I2C_CTL_SPEED_MASK;
  reg |= I2C_CTL_SPEED_FS;
  i2c_putreg(base, I2C_CTL, reg);

  /* 写入 HCNT/LCNT */

  i2c_putreg(base, I2C_FS_SCL_HCNT, hcnt);
  i2c_putreg(base, I2C_FS_SCL_LCNT, lcnt);

  /* RX FIFO threshold = FIFO_DEPTH/2 */

  i2c_putreg(base, I2C_RX_TL, I2C_FIFO_DEPTH / 2 - 1);
}

/****************************************************************************
 * Name: d13x_i2c_transfer_one
 *
 * Description:
 *   执行单条 I2C 消息传输
 *
 ****************************************************************************/

static int d13x_i2c_transfer_one(struct d13x_i2c_dev_s *priv,
                                  FAR struct i2c_msg_s *msg)
{
  uint32_t base = priv->base;
  int remaining;
  int ret = OK;
  uint32_t timeout;
  uint32_t reg_val;

  /* 等待总线空闲 */

  ret = i2c_wait_bus_idle(base, I2C_TIMEOUT_MS);
  if (ret < 0)
    {
      return ret;
    }

  /* 禁用模块 → 设置目标地址 → 重新使能 */

  i2c_module_disable(base);

  reg_val = i2c_getreg(base, I2C_TAR);
  reg_val &= ~0x3ff;
  reg_val |= (msg->addr & 0x3ff);
  i2c_putreg(base, I2C_TAR, reg_val);

  /* 确保 master 模式 + restart enable */

  reg_val = i2c_getreg(base, I2C_CTL);
  reg_val |= I2C_CTL_MASTER | I2C_CTL_RESTART_EN;
  i2c_putreg(base, I2C_CTL, reg_val);

  /* 清除所有中断 */

  i2c_putreg(base, I2C_INTR_CLR, 0xffff);

  i2c_module_enable(base);

  if (msg->flags & I2C_M_READ)
    {
      /* === 读操作 === */

      remaining = msg->length;

      while (remaining > 0)
        {
          int burst = remaining > I2C_FIFO_DEPTH ?
                      I2C_FIFO_DEPTH : remaining;
          int i;

          /* 发送读命令 */

          for (i = 0; i < burst - 1; i++)
            {
              i2c_putreg(base, I2C_DATA_CMD, I2C_DATA_CMD_READ);
            }

          /* 最后一个字节带 STOP */

          if (remaining <= I2C_FIFO_DEPTH)
            {
              i2c_putreg(base, I2C_DATA_CMD,
                         I2C_DATA_CMD_READ | I2C_DATA_CMD_STOP);
            }
          else
            {
              i2c_putreg(base, I2C_DATA_CMD, I2C_DATA_CMD_READ);
            }

          /* 等待数据到达 */

          timeout = I2C_TIMEOUT_MS;
          while (i2c_getreg(base, I2C_RXFLR) < burst)
            {
              if (i2c_getreg(base, I2C_INTR_RAW_STAT) & I2C_INTR_TX_ABRT)
                {
                  i2c_putreg(base, I2C_INTR_CLR, 0xffff);
                  return -EIO;
                }

              if (--timeout == 0)
                {
                  return -ETIMEDOUT;
                }

              up_udelay(100);
            }

          /* 读取数据 */

          for (i = 0; i < burst; i++)
            {
              *msg->buffer++ = (uint8_t)(i2c_getreg(base, I2C_DATA_CMD) & 0xff);
            }

          remaining -= burst;
        }

      /* 等待 STOP */

      timeout = I2C_TIMEOUT_MS;
      while (!(i2c_getreg(base, I2C_INTR_RAW_STAT) & I2C_INTR_STOP_DET))
        {
          if (--timeout == 0)
            {
              return -ETIMEDOUT;
            }

          up_udelay(100);
        }
    }
  else
    {
      /* === 写操作 === */

      remaining = msg->length;

      while (remaining > 0)
        {
          int burst = remaining > I2C_FIFO_DEPTH ?
                      I2C_FIFO_DEPTH : remaining;
          int i;

          for (i = 0; i < burst - 1; i++)
            {
              /* 等待 TX FIFO 有空间 */

              timeout = I2C_TIMEOUT_MS;
              while (i2c_getreg(base, I2C_TXFLR) >= I2C_FIFO_DEPTH)
                {
                  if (i2c_getreg(base, I2C_INTR_RAW_STAT) & I2C_INTR_TX_ABRT)
                    {
                      i2c_putreg(base, I2C_INTR_CLR, 0xffff);
                      return -EIO;
                    }

                  if (--timeout == 0)
                    {
                      return -ETIMEDOUT;
                    }

                  up_udelay(100);
                }

              i2c_putreg(base, I2C_DATA_CMD, *msg->buffer++);
            }

          /* 最后一个字节带 STOP */

          timeout = I2C_TIMEOUT_MS;
          while (i2c_getreg(base, I2C_TXFLR) >= I2C_FIFO_DEPTH)
            {
              if (--timeout == 0)
                {
                  return -ETIMEDOUT;
                }

              up_udelay(100);
            }

          i2c_putreg(base, I2C_DATA_CMD,
                     I2C_DATA_CMD_STOP | (*msg->buffer++));

          remaining -= burst;
        }

      /* 等待 STOP */

      timeout = I2C_TIMEOUT_MS;
      while (!(i2c_getreg(base, I2C_INTR_RAW_STAT) & I2C_INTR_STOP_DET))
        {
          if (--timeout == 0)
            {
              return -ETIMEDOUT;
            }

          up_udelay(100);
        }
    }

  /* 清除中断 */

  i2c_putreg(base, I2C_INTR_CLR, 0xffff);

  return msg->length;
}

/****************************************************************************
 * Name: d13x_i2c_transfer
 ****************************************************************************/

static int d13x_i2c_transfer(FAR struct i2c_master_s *dev,
                              FAR struct i2c_msg_s *msgs, int count)
{
  FAR struct d13x_i2c_dev_s *priv = (FAR struct d13x_i2c_dev_s *)dev;
  int i;
  int ret;

  DEBUGASSERT(dev);
  DEBUGASSERT(msgs);
  DEBUGASSERT(count > 0);

  for (i = 0; i < count; i++)
    {
      ret = d13x_i2c_transfer_one(priv, &msgs[i]);
      if (ret < 0)
        {
          return ret;
        }
    }

  return OK;
}

/****************************************************************************
 * Name: d13x_i2c_setup
 ****************************************************************************/

static int d13x_i2c_setup(FAR struct i2c_master_s *dev)
{
  FAR struct d13x_i2c_dev_s *priv = (FAR struct d13x_i2c_dev_s *)dev;
  uint32_t reg;

  DEBUGASSERT(dev);

  /* 确保模块禁用 */

  i2c_module_disable(priv->base);

  /* 设置 master 模式 */

  reg = i2c_getreg(priv->base, I2C_CTL);
  reg |= I2C_CTL_MASTER | I2C_CTL_RESTART_EN;
  i2c_putreg(priv->base, I2C_CTL, reg);

  /* 设置 SCL 时序 (APB0 = 100MHz) */

  d13x_i2c_set_speed(priv->base, D13X_APB0_FREQ);

  return OK;
}

/****************************************************************************
 * Name: d13x_i2c_shutdown
 ****************************************************************************/

static int d13x_i2c_shutdown(FAR struct i2c_master_s *dev)
{
  FAR struct d13x_i2c_dev_s *priv = (FAR struct d13x_i2c_dev_s *)dev;

  DEBUGASSERT(dev);

  i2c_module_disable(priv->base);

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: d13x_i2c_initialize
 *
 * Description:
 *   初始化指定的 I2C 总线并返回 i2c_master_s 句柄
 *
 * Input Parameters:
 *   bus - I2C 总线编号 (0, 1, 2)
 *
 * Returned Value:
 *   成功返回 i2c_master_s 指针，失败返回 NULL
 *
 ****************************************************************************/

FAR struct i2c_master_s *d13x_i2c_initialize(int bus)
{
  FAR struct d13x_i2c_dev_s *priv;

  switch (bus)
    {
      case 0:
        priv = &g_d13x_i2c0;
        break;
      case 1:
        priv = &g_d13x_i2c1;
        break;
      case 2:
        priv = &g_d13x_i2c2;
        break;
      default:
        ierr("Invalid I2C bus: %d\n", bus);
        return NULL;
    }

  /* 执行 setup */

  d13x_i2c_setup(&priv->dev);

  iinfo("I2C%d initialized at 0x%08" PRIx32 "\n", bus, priv->base);

  return &priv->dev;
}

/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_lvds.c
 *
 * D13x LVDS 显示控制器驱动 (NuttX FB 框架)
 * 参考: luban-lite drv_lvds.c + aic_hal_lvds.h
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/compiler.h>
#include <nuttx/arch.h>
#include <nuttx/video/fb.h>
#include <stdint.h>
#include <string.h>
#include <assert.h>
#include <debug.h>

#include "chip.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* LVDS 控制器基地址 (来源: aic_soc.h) */

#define D13X_LVDS_BASE         0x18810000
#define D13X_DE_BASE           0x18A00000

/* LVDS 寄存器偏移 (来源: aic_hal_lvds.h) */

#define LVDS_CTL               0x00
#define LVDS_CK_CFG            0x10
#define LVDS_0_SWAP            0x20
#define LVDS_1_SWAP            0x24
#define LVDS_0_POL_CTL         0x28
#define LVDS_1_POL_CTL         0x2C
#define LVDS_0_PHY_CTL         0x30
#define LVDS_1_PHY_CTL         0x34
#define LVDS_VERSION           0xFC

/* LVDS_CTL 位定义 */

#define LVDS_CTL_MODE_MASK     (3 << 8)
#define LVDS_CTL_MODE(x)       (((x) & 0x3) << 8)
#define LVDS_CTL_LINK_MASK     (3 << 4)
#define LVDS_CTL_LINK(x)       (((x) & 0x3) << 4)
#define LVDS_CTL_SWAP_EN       (1 << 2)
#define LVDS_CTL_SYNC_MODE_EN  (1 << 1)
#define LVDS_CTL_EN            (1 << 0)

/* LVDS PHY 配置 (来源: disp_conf.h) */

#define AIC_LVDS_SYNC_MODE_EN  1
#define AIC_LVDS_LINK_SWAP_EN  0
#define AIC_LVDS_LINES         0x43210
#define AIC_LVDS_POL           0x0
#define AIC_LVDS_PHY           0xFA

/* LVDS 模式 (来源: disp_com.h) */

#define LVDS_NS                0x0
#define LVDS_JEIDA_24BIT       0x1
#define LVDS_SINGLE_LINK0      0x0

/* 面板时序参数 (1024x600 LVDS 面板) */

#define PANEL_HACTIVE          1024
#define PANEL_VACTIVE          600
#define PANEL_HBP              46
#define PANEL_HFP              20
#define PANEL_HSW              1
#define PANEL_VBP              23
#define PANEL_VFP              10
#define PANEL_VSW              3
#define PANEL_PIXELCLOCK       51000000  /* 51MHz */

/* PLL 最小频率 */

#define PLL_DISP_FREQ_MIN      (360 * 1000 * 1000)

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct d13x_lvds_dev_s
{
  uint32_t           base;       /* LVDS 寄存器基地址 */
  uint32_t           pixclk;     /* 像素时钟 */
  uint32_t           sclk;       /* LVDS 串行时钟 */
  uint32_t           pll_disp;   /* PLL Display 频率 */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct d13x_lvds_dev_s g_lvds_dev;

/* NuttX FB vtable */

static const struct fb_vtable_s g_fb_vtable;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static inline void lvds_putreg(uint32_t offset, uint32_t val)
{
  putreg32(val, D13X_LVDS_BASE + offset);
}

static inline uint32_t lvds_getreg(uint32_t offset)
{
  return getreg32(D13X_LVDS_BASE + offset);
}

static inline void de_putreg(uint32_t offset, uint32_t val)
{
  putreg32(val, D13X_DE_BASE + offset);
}

static inline uint32_t de_getreg(uint32_t offset)
{
  return getreg32(D13X_DE_BASE + offset);
}

/****************************************************************************
 * Name: d13x_lvds_calc_clocks
 *
 * Description:
 *   计算 LVDS 时钟参数
 *
 ****************************************************************************/

static void d13x_lvds_calc_clocks(struct d13x_lvds_dev_s *dev)
{
  /* Single Link: sclk = pixclk * 7 */

  dev->sclk = dev->pixclk * 7;

  /* 计算 PLL 频率，确保 >= PLL_DISP_FREQ_MIN */

  dev->pll_disp = dev->sclk;
  uint32_t mult = 2;
  while (dev->pll_disp < PLL_DISP_FREQ_MIN)
    {
      dev->pll_disp = dev->sclk * mult;
      mult *= 2;
    }

  iinfo("LVDS: pixclk=%lu, sclk=%lu, pll_disp=%lu\n",
        (unsigned long)dev->pixclk,
        (unsigned long)dev->sclk,
        (unsigned long)dev->pll_disp);
}

/****************************************************************************
 * Name: d13x_lvds_enable
 *
 * Description:
 *   使能 LVDS 控制器
 *
 ****************************************************************************/

static void d13x_lvds_enable(void)
{
  /* 配置 LVDS 线序 */

  lvds_putreg(LVDS_0_SWAP, AIC_LVDS_LINES);
  lvds_putreg(LVDS_1_SWAP, AIC_LVDS_LINES);

  /* 配置极性 */

  lvds_putreg(LVDS_0_POL_CTL, AIC_LVDS_POL);
  lvds_putreg(LVDS_1_POL_CTL, AIC_LVDS_POL);

  /* 配置 PHY */

  lvds_putreg(LVDS_0_PHY_CTL, AIC_LVDS_PHY);
  lvds_putreg(LVDS_1_PHY_CTL, AIC_LVDS_PHY);

  /* 配置 LVDS 控制寄存器 */

  uint32_t ctl = 0;
  ctl |= LVDS_CTL_MODE(LVDS_NS);          /* VESA 模式 */
  ctl |= LVDS_CTL_LINK(LVDS_SINGLE_LINK0);
  ctl |= AIC_LVDS_LINK_SWAP_EN ? LVDS_CTL_SWAP_EN : 0;
  ctl |= AIC_LVDS_SYNC_MODE_EN ? LVDS_CTL_SYNC_MODE_EN : 0;
  lvds_putreg(LVDS_CTL, ctl);

  /* 使能 LVDS */

  lvds_putreg(LVDS_CTL, ctl | LVDS_CTL_EN);
}

/****************************************************************************
 * Name: d13x_lvds_disable
 ****************************************************************************/

static void d13x_lvds_disable(void)
{
  uint32_t ctl = lvds_getreg(LVDS_CTL);
  ctl &= ~LVDS_CTL_EN;
  lvds_putreg(LVDS_CTL, ctl);
}

/****************************************************************************
 * NuttX FB 操作 (简化实现)
 ****************************************************************************/

static int d13x_fb_getvideoinfo(FAR struct fb_vtable_s *vtable,
                                 FAR struct fb_videoinfo_s *vinfo)
{
  vinfo->xres         = PANEL_HACTIVE;
  vinfo->yres         = PANEL_VACTIVE;
  vinfo->nplanes      = 1;
  vinfo->fbmem        = NULL;
  vinfo->fblen        = PANEL_HACTIVE * PANEL_VACTIVE * 4;  /* 32bpp */
  vinfo->bpp          = 32;
  vinfo->fmt          = FB_FMT_RGB32;  /* 必须显式设置! */
  return OK;
}

static int d13x_fb_getplaneinfo(FAR struct fb_vtable_s *vtable,
                                 int planeno,
                                 FAR struct fb_planeinfo_s *pinfo)
{
  pinfo->bpp          = 32;
  pinfo->xres_virtual = PANEL_HACTIVE;
  pinfo->yres_virtual = PANEL_VACTIVE;
  pinfo->stride       = PANEL_HACTIVE * 4;
  pinfo->fblen        = PANEL_HACTIVE * PANEL_VACTIVE * 4;
  pinfo->fbmem        = NULL;
  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: d13x_lvds_initialize
 *
 * Description:
 *   初始化 D13x LVDS 显示控制器
 *
 * Returned Value:
 *   成功返回 0，失败返回负错误码
 *
 ****************************************************************************/

int d13x_lvds_initialize(void)
{
  struct d13x_lvds_dev_s *dev = &g_lvds_dev;

  /* 配置面板参数 */

  dev->base   = D13X_LVDS_BASE;
  dev->pixclk = PANEL_PIXELCLOCK;

  /* 计算时钟 */

  d13x_lvds_calc_clocks(dev);

  /* 使能 LVDS 控制器 */

  d13x_lvds_enable();

  iinfo("LVDS initialized: %dx%d @ %luMHz\n",
        PANEL_HACTIVE, PANEL_VACTIVE,
        (unsigned long)(dev->pixclk / 1000000));

  return OK;
}

/****************************************************************************
 * Name: d13x_fb_getops
 *
 * Description:
 *   获取 FB vtable (用于 fb_register)
 *
 ****************************************************************************/

FAR const struct fb_vtable_s *d13x_fb_getops(void)
{
  return &g_fb_vtable;
}

/****************************************************************************
 * Static FB vtable
 ****************************************************************************/

static const struct fb_vtable_s g_fb_vtable =
{
  .getvideoinfo = d13x_fb_getvideoinfo,
  .getplaneinfo = d13x_fb_getplaneinfo,
};

/****************************************************************************
 * vendor/artinchip/boards/d13x-hengshan-pi/src/artinchip_gt911.c
 *
 * D13x GT911 触摸屏板级回调实现
 * 参考: luban-lite gt911.h + NuttX gt9xx.h
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/compiler.h>
#include <nuttx/arch.h>
#include <nuttx/irq.h>
#include <nuttx/input/gt911.h>
#include <stdint.h>
#include <string.h>
#include <assert.h>
#include <debug.h>

#include "chip.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* GT911 GPIO 引脚 (来源: 历史经验 + Schematic) */

/* PA0 = GT911 RST (GPIO 模式) */
/* PA2 = GT911 INT (GPIO 中断模式) */

/* D13x GPIO 基地址 */

#define D13X_GPIO_BASE         0x18700000

/* GPIO 寄存器偏移 (来源: D13x User Manual) */

#define GPIO_SWPORTA_DR        0x00   /* 端口 A 数据寄存器 */
#define GPIO_SWPORTA_DDR       0x04   /* 端口 A 数据方向寄存器 */
#define GPIO_INT_EN            0x30   /* 中断使能 */
#define GPIO_INT_MASK          0x34   /* 中断屏蔽 */
#define GPIO_INT_TYPE          0x38   /* 中断类型 (边沿/电平) */
#define GPIO_INT_POL           0x3C   /* 中断极性 */
#define GPIO_INT_STATUS        0x50   /* 中断状态 */
#define GPIO_PORT_EOI          0x4C   /* 端口中断清除 */

/* GPIO 引脚号计算: PA = 0*32 + pin */

#define GT911_RST_PIN          (0 * 32 + 0)   /* PA0 */
#define GT911_INT_PIN          (0 * 32 + 2)   /* PA2 */

/* GT911 I2C 地址 (来源: gt911.h) */

#define GT911_I2C_ADDR         0x5D

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static inline void gpio_putreg(uint32_t offset, uint32_t val)
{
  putreg32(val, D13X_GPIO_BASE + offset);
}

static inline uint32_t gpio_getreg(uint32_t offset)
{
  return getreg32(D13X_GPIO_BASE + offset);
}

static void gpio_set_direction(int pin, int output)
{
  uint32_t reg = gpio_getreg(GPIO_SWPORTA_DDR);
  if (output)
    {
      reg |= (1 << pin);
    }
  else
    {
      reg &= ~(1 << pin);
    }
  gpio_putreg(GPIO_SWPORTA_DDR, reg);
}

static void gpio_set_value(int pin, int value)
{
  uint32_t reg = gpio_getreg(GPIO_SWPORTA_DR);
  if (value)
    {
      reg |= (1 << pin);
    }
  else
    {
      reg &= ~(1 << pin);
    }
  gpio_putreg(GPIO_SWPORTA_DR, reg);
}

/****************************************************************************
 * GT911 板级回调实现
 ****************************************************************************/

static int gt911_irq_attach(const struct gt9xx_board_s *state,
                             xcpt_t isr, FAR void *arg)
{
  irqstate_t flags;

  /* 配置 PA2 为 GPIO 输入 */

  gpio_set_direction(GT911_INT_PIN, 0);

  /* 禁用 PA2 中断 */

  uint32_t reg = gpio_getreg(GPIO_INT_EN);
  reg &= ~(1 << GT911_INT_PIN);
  gpio_putreg(GPIO_INT_EN, reg);

  /* 配置 PA2 为上升沿触发中断 */

  reg = gpio_getreg(GPIO_INT_TYPE);
  reg |= (1 << GT911_INT_PIN);       /* 边沿触发 */
  gpio_putreg(GPIO_INT_TYPE, reg);

  reg = gpio_getreg(GPIO_INT_POL);
  reg |= (1 << GT911_INT_PIN);       /* 上升沿 */
  gpio_putreg(GPIO_INT_POL, reg);

  /* 取消屏蔽 */

  reg = gpio_getreg(GPIO_INT_MASK);
  reg &= ~(1 << GT911_INT_PIN);
  gpio_putreg(GPIO_INT_MASK, reg);

  /* 附加中断处理函数 */

  flags = enter_critical_section();
  irq_attach(GT911_INT_PIN, isr, arg);
  leave_critical_section(flags);

  iinfo("GT911 IRQ attached to PA2\n");

  return OK;
}

static void gt911_irq_enable(const struct gt9xx_board_s *state, bool enable)
{
  uint32_t reg = gpio_getreg(GPIO_INT_EN);

  if (enable)
    {
      reg |= (1 << GT911_INT_PIN);
    }
  else
    {
      reg &= ~(1 << GT911_INT_PIN);
    }

  gpio_putreg(GPIO_INT_EN, reg);
}

static int gt911_set_power(const struct gt9xx_board_s *state, bool on)
{
  /* 配置 PA0 为 GPIO 输出 */

  gpio_set_direction(GT911_RST_PIN, 1);

  if (on)
    {
      /* 上电复位序列: 拉低 → 延时 → 拉高 */

      gpio_set_value(GT911_RST_PIN, 0);
      up_mdelay(20);
      gpio_set_value(GT911_RST_PIN, 1);
      up_mdelay(100);  /* 等待 GT911 启动 */
    }
  else
    {
      /* 关闭: 拉低 RST */

      gpio_set_value(GT911_RST_PIN, 0);
    }

  iinfo("GT911 power %s\n", on ? "on" : "off");

  return OK;
}

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct gt9xx_board_s g_gt911_board =
{
  .irq_attach = gt911_irq_attach,
  .irq_enable = gt911_irq_enable,
  .set_power  = gt911_set_power,
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: d13x_gt911_initialize
 *
 * Description:
 *   初始化 D13x GT911 触摸屏
 *
 * Returned Value:
 *   成功返回 0，失败返回负错误码
 *
 ****************************************************************************/

int d13x_gt911_initialize(void)
{
  FAR struct i2c_master_s *i2c;

  /* 获取 I2C0 总线 */

  i2c = d13x_i2c_initialize(0);
  if (i2c == NULL)
    {
      ierr("Failed to get I2C0 bus\n");
      return -ENODEV;
    }

  /* 上电复位 GT911 */

  gt911_set_power(&g_gt911_board, true);

  /* 注册 GT911 驱动 */

  int ret = gt9xx_register("/dev/input0", i2c,
                            GT911_I2C_ADDR, &g_gt911_board);
  if (ret < 0)
    {
      ierr("Failed to register GT911: %d\n", ret);
      return ret;
    }

  iinfo("GT911 registered at /dev/input0 (I2C addr 0x%02x)\n",
        GT911_I2C_ADDR);

  return OK;
}

