  gpio_set_direction(GT911_INT_PIN, 0);

  /* 禁用 PA2 中断 */

  uint32_t reg = gpio_getreg(GPIO_INT_EN);
  reg &= ~(1 << GT911_INT_PIN);
  gpio_putreg(GPIO_INT_EN, reg);

  /* 配置 PA2 为上升沿触发中断 */

  reg = gpio_getreg(GPIO_INT_TYPE);
  reg |= (1 << GT911_INT_PIN);       /* 边沿触发 */
  gpio_putreg(GPIO_INT_TYPE, reg);

  reg = gpio_getreg(GPIO_INT_POL);
  reg |= (1 << GT911_INT_PIN);       /* 上升沿 */
  gpio_putreg(GPIO_INT_POL, reg);

  /* 取消屏蔽 */

  reg = gpio_getreg(GPIO_INT_MASK);
  reg &= ~(1 << GT911_INT_PIN);
  gpio_putreg(GPIO_INT_MASK, reg);

  /* 附加中断处理函数 */

  flags = enter_critical_section();
  irq_attach(GT911_INT_PIN, isr, arg);
  leave_critical_section(flags);

  iinfo("GT911 IRQ attached to PA2\n");

