/****************************************************************************
 * vendor/artinchip/boards/d13x-hengshan-pi/src/artinchip_gt911.c
 *
 * D13x GT911 触摸屏板级回调实现
 *
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/compiler.h>
#include <nuttx/arch.h>
#include <nuttx/irq.h>
#include <nuttx/i2c/i2c_master.h>
#include <stdint.h>
#include <debug.h>

#include "chip.h"

/* GT911 板级回调声明 (定义在同文件底部) */

static const struct gt9xx_board_s g_gt911_board;

/* I2C 初始化声明 (定义在 artinchip_i2c.c) */

FAR struct i2c_master_s *d13x_i2c_initialize(int bus);

/* GT911 驱动注册声明 (NuttX 内置) */

extern int gt9xx_register(FAR const char *devpath,
                           FAR struct i2c_master_s *dev,
                           uint8_t i2c_devaddr,
                           const struct gt9xx_board_s *board_config);

/* D13x GPIO 基地址 */

#define D13X_GPIO_BASE         0x18700000

/* GPIO 寄存器偏移 */

#define GPIO_SWPORTA_DR        0x00
#define GPIO_SWPORTA_DDR       0x04
#define GPIO_INT_EN            0x30
#define GPIO_INT_MASK          0x34
#define GPIO_INT_TYPE          0x38
#define GPIO_INT_POL           0x3C

/* GT911 引脚 */

#define GT911_RST_PIN          (0 * 32 + 0)   /* PA0 */
#define GT911_INT_PIN          (0 * 32 + 2)   /* PA2 */
#define GT911_I2C_ADDR         0x5D

/****************************************************************************
 * GPIO 操作
 ****************************************************************************/

static inline void gpio_putreg(uint32_t offset, uint32_t val)
{
  putreg32(val, D13X_GPIO_BASE + offset);
}

static inline uint32_t gpio_getreg(uint32_t offset)
{
  return getreg32(D13X_GPIO_BASE + offset);
}

static void gpio_set_direction(int pin, int output)
{
  uint32_t reg = gpio_getreg(GPIO_SWPORTA_DDR);
  if (output)
    reg |= (1 << pin);
  else
    reg &= ~(1 << pin);
  gpio_putreg(GPIO_SWPORTA_DDR, reg);
}

static void gpio_set_value(int pin, int value)
{
  uint32_t reg = gpio_getreg(GPIO_SWPORTA_DR);
  if (value)
    reg |= (1 << pin);
  else
    reg &= ~(1 << pin);
  gpio_putreg(GPIO_SWPORTA_DR, reg);
}

/****************************************************************************
 * GT911 板级回调
 ****************************************************************************/

static int gt911_irq_attach(const struct gt9xx_board_s *state,
                             xcpt_t isr, FAR void *arg)
{
  uint32_t reg;

  gpio_set_direction(GT911_INT_PIN, 0);

  /* 禁用 GPIO 中断 */

  reg = gpio_getreg(GPIO_INT_EN);
  reg &= ~(1 << GT911_INT_PIN);
  gpio_putreg(GPIO_INT_EN, reg);

  /* 边沿触发 + 上升沿 */

  reg = gpio_getreg(GPIO_INT_TYPE);
  reg |= (1 << GT911_INT_PIN);
  gpio_putreg(GPIO_INT_TYPE, reg);

  reg = gpio_getreg(GPIO_INT_POL);
  reg |= (1 << GT911_INT_PIN);
  gpio_putreg(GPIO_INT_POL, reg);

  /* 取消 GPIO 屏蔽 */

  reg = gpio_getreg(GPIO_INT_MASK);
  reg &= ~(1 << GT911_INT_PIN);
  gpio_putreg(GPIO_INT_MASK, reg);

  /* 挂载 CLIC 中断 */

  irqstate_t flags = up_irq_save();
  irq_attach(D13X_IRQ_GPIO, isr, arg);
  up_disable_irq(D13X_IRQ_GPIO);
  up_irq_restore(flags);

  return OK;
}

static void gt911_irq_enable(const struct gt9xx_board_s *state, bool enable)
{
  uint32_t reg = gpio_getreg(GPIO_INT_EN);

  if (enable)
    reg |= (1 << GT911_INT_PIN);
  else
    reg &= ~(1 << GT911_INT_PIN);

  gpio_putreg(GPIO_INT_EN, reg);

  if (enable)
    up_enable_irq(D13X_IRQ_GPIO);
  else
    up_disable_irq(D13X_IRQ_GPIO);
}

static int gt911_set_power(const struct gt9xx_board_s *state, bool on)
{
  gpio_set_direction(GT911_RST_PIN, 1);

  if (on)
    {
      gpio_set_value(GT911_RST_PIN, 0);
      up_mdelay(20);
      gpio_set_value(GT911_RST_PIN, 1);
      up_mdelay(100);
    }
  else
    {
      gpio_set_value(GT911_RST_PIN, 0);
    }

  return OK;
}

static const struct gt9xx_board_s g_gt911_board =
{
  .irq_attach = gt911_irq_attach,
  .irq_enable = gt911_irq_enable,
  .set_power  = gt911_set_power,
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int d13x_gt911_initialize(void)
{
  FAR struct i2c_master_s *bus;

  bus = d13x_i2c_initialize(0);
  if (bus == NULL)
    {
      return -ENODEV;
    }

  gt911_set_power(&g_gt911_board, true);

  int ret = gt9xx_register("/dev/input0", bus,
                            GT911_I2C_ADDR, &g_gt911_board);
  if (ret < 0)
    {
      ierr("GT911 register failed: %d\n", ret);
      return ret;
    }

  return OK;
}

