/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_lvds.c
 *
 * D13x LVDS 显示控制器驱动 (NuttX FB 框架)
 * 参考: luban-lite drv_lvds.c + aic_hal_lvds.h
 *
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/compiler.h>
#include <nuttx/arch.h>
#include <nuttx/kmalloc.h>
#include <nuttx/video/fb.h>
#include <stdint.h>
#include <string.h>
#include <assert.h>
#include <debug.h>

#include "chip.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define D13X_LVDS_BASE         0x18810000
#define D13X_DE_BASE           0x18A00000

/* LVDS 寄存器偏移 */

#define LVDS_CTL               0x00
#define LVDS_CK_CFG            0x10
#define LVDS_0_SWAP            0x20
#define LVDS_1_SWAP            0x24
#define LVDS_0_POL_CTL         0x28
#define LVDS_1_POL_CTL         0x2C
#define LVDS_0_PHY_CTL         0x30
#define LVDS_1_PHY_CTL         0x34

/* LVDS_CTL 位定义 */

#define LVDS_CTL_MODE_MASK     (3 << 8)
#define LVDS_CTL_MODE(x)       (((x) & 0x3) << 8)
#define LVDS_CTL_LINK_MASK     (3 << 4)
#define LVDS_CTL_LINK(x)       (((x) & 0x3) << 4)
#define LVDS_CTL_SWAP_EN       (1 << 2)
#define LVDS_CTL_SYNC_MODE_EN  (1 << 1)
#define LVDS_CTL_EN            (1 << 0)

/* LVDS PHY 配置 */

#define AIC_LVDS_SYNC_MODE_EN  1
#define AIC_LVDS_LINK_SWAP_EN  0
#define AIC_LVDS_LINES         0x43210
#define AIC_LVDS_POL           0x0
#define AIC_LVDS_PHY           0xFA

/* LVDS 模式 */

#define LVDS_NS                0x0
#define LVDS_SINGLE_LINK0      0x0

/* 面板时序参数 */

#define PANEL_HACTIVE          1024
#define PANEL_VACTIVE          600
#define PANEL_PIXELCLOCK       51000000

/* 帧缓冲大小 = 宽 × 高 × 每像素字节数(32bpp) */

#define FB_SIZE                (PANEL_HACTIVE * PANEL_VACTIVE * 4)

/* PLL 最小频率 */

#define PLL_DISP_FREQ_MIN      (360 * 1000 * 1000)

/****************************************************************************
 * Private Data
 ****************************************************************************/

struct d13x_lvds_dev_s
{
  uint32_t           base;
  uint32_t           pixclk;
  uint32_t           sclk;
  uint32_t           pll_disp;
  FAR void          *fbmem;        /* 帧缓冲内存 */
  size_t             fblen;
  bool               initialized;
};

static struct d13x_lvds_dev_s g_lvds_dev;

/****************************************************************************
 * Private Functions - 寄存器操作
 ****************************************************************************/

static inline void lvds_putreg(uint32_t offset, uint32_t val)
{
  putreg32(val, D13X_LVDS_BASE + offset);
}

static inline uint32_t lvds_getreg(uint32_t offset)
{
  return getreg32(D13X_LVDS_BASE + offset);
}

/****************************************************************************
 * Private Functions - LVDS 控制器
 ****************************************************************************/

static void d13x_lvds_calc_clocks(struct d13x_lvds_dev_s *dev)
{
  dev->sclk = dev->pixclk * 7;

  dev->pll_disp = dev->sclk;
  uint32_t mult = 2;
  while (dev->pll_disp < PLL_DISP_FREQ_MIN)
    {
      dev->pll_disp = dev->sclk * mult;
      mult *= 2;
    }
}

static void d13x_lvds_enable(struct d13x_lvds_dev_s *dev)
{
  lvds_putreg(LVDS_0_SWAP, AIC_LVDS_LINES);
  lvds_putreg(LVDS_1_SWAP, AIC_LVDS_LINES);
  lvds_putreg(LVDS_0_POL_CTL, AIC_LVDS_POL);
  lvds_putreg(LVDS_1_POL_CTL, AIC_LVDS_POL);
  lvds_putreg(LVDS_0_PHY_CTL, AIC_LVDS_PHY);
  lvds_putreg(LVDS_1_PHY_CTL, AIC_LVDS_PHY);

  uint32_t ctl = 0;
  ctl |= LVDS_CTL_MODE(LVDS_NS);
  ctl |= LVDS_CTL_LINK(LVDS_SINGLE_LINK0);
  if (AIC_LVDS_LINK_SWAP_EN)
    {
      ctl |= LVDS_CTL_SWAP_EN;
    }

  if (AIC_LVDS_SYNC_MODE_EN)
    {
      ctl |= LVDS_CTL_SYNC_MODE_EN;
    }

  lvds_putreg(LVDS_CTL, ctl);
  lvds_putreg(LVDS_CTL, ctl | LVDS_CTL_EN);
}

static void d13x_lvds_disable(void)
{
  uint32_t ctl = lvds_getreg(LVDS_CTL);
  ctl &= ~LVDS_CTL_EN;
  lvds_putreg(LVDS_CTL, ctl);
}

/****************************************************************************
 * Private Functions - FB vtable 回调
 ****************************************************************************/

static int d13x_fb_open(FAR struct fb_vtable_s *vtable)
{
  return OK;
}

static int d13x_fb_close(FAR struct fb_vtable_s *vtable)
{
  return OK;
}

static int d13x_fb_getvideoinfo(FAR struct fb_vtable_s *vtable,
                                 FAR struct fb_videoinfo_s *vinfo)
{
  vinfo->fmt    = FB_FMT_RGB32;
  vinfo->xres   = PANEL_HACTIVE;
  vinfo->yres   = PANEL_VACTIVE;
  vinfo->nplanes = 1;
  return OK;
}

static int d13x_fb_getplaneinfo(FAR struct fb_vtable_s *vtable,
                                 int planeno,
                                 FAR struct fb_planeinfo_s *pinfo)
{
  struct d13x_lvds_dev_s *dev = &g_lvds_dev;

  pinfo->bpp          = 32;
  pinfo->xres_virtual = PANEL_HACTIVE;
  pinfo->yres_virtual = PANEL_VACTIVE;
  pinfo->stride       = PANEL_HACTIVE * 4;
  pinfo->fblen        = dev->fblen;
  pinfo->fbmem        = dev->fbmem;
  pinfo->display      = 0;
  pinfo->xoffset      = 0;
  pinfo->yoffset      = 0;
  return OK;
}

static int d13x_fb_pandisplay(FAR struct fb_vtable_s *vtable,
                               FAR struct fb_planeinfo_s *pinfo)
{
  /* 单缓冲模式，pan display 不做任何事 */

  return OK;
}

/****************************************************************************
 * Private Data - FB vtable
 ****************************************************************************/

static const struct fb_vtable_s g_fb_vtable =
{
  .open        = d13x_fb_open,
  .close       = d13x_fb_close,
  .getvideoinfo = d13x_fb_getvideoinfo,
  .getplaneinfo = d13x_fb_getplaneinfo,
  .pandisplay  = d13x_fb_pandisplay,
};

/****************************************************************************
 * Public Functions - NuttX FB 平台接口
 ****************************************************************************/

int up_fbinitialize(int display)
{
  struct d13x_lvds_dev_s *dev = &g_lvds_dev;

  if (dev->initialized)
    {
      return OK;
    }

  dev->base   = D13X_LVDS_BASE;
  dev->pixclk = PANEL_PIXELCLOCK;
  dev->fblen  = FB_SIZE;

  /* 分配帧缓冲内存（PSRAM 区域，cacheable） */

  dev->fbmem = kumm_memalign(64, dev->fblen);
  if (dev->fbmem == NULL)
    {
      ierr("Failed to allocate framebuffer (%zu bytes)\n", dev->fblen);
      return -ENOMEM;
    }

  memset(dev->fbmem, 0, dev->fblen);

  /* 计算时钟并使能 LVDS 控制器 */

  d13x_lvds_calc_clocks(dev);
  d13x_lvds_enable(dev);

  dev->initialized = true;

  iinfo("LVDS FB: %dx%d @ %luMHz, fbmem=%p, fblen=%zu\n",
        PANEL_HACTIVE, PANEL_VACTIVE,
        (unsigned long)(dev->pixclk / 1000000),
        dev->fbmem, dev->fblen);

  return OK;
}

FAR struct fb_vtable_s *up_fbgetvplane(int display, int vplane)
{
  if (display == 0 && vplane == 0)
    {
      return (FAR struct fb_vtable_s *)&g_fb_vtable;
    }

  return NULL;
}

void up_fbuninitialize(int display)
{
  struct d13x_lvds_dev_s *dev = &g_lvds_dev;

  d13x_lvds_disable();

  if (dev->fbmem != NULL)
    {
      kumm_free(dev->fbmem);
      dev->fbmem = NULL;
    }

  dev->initialized = false;
}

